CREATE TYPE "SellerContactAttemptStatus" AS ENUM ('DRAFT','APPROVED_NOT_SENT','MANUALLY_RECORDED','DELIVERED','FAILED','SUPPRESSED','CANCELLED');
CREATE TYPE "SellerAuthorityStatus" AS ENUM ('UNKNOWN','CLAIMED','DOCUMENTED','VERIFIED','REJECTED');
CREATE TYPE "SellerRepresentationStatus" AS ENUM ('UNKNOWN','UNREPRESENTED','AGENT_REPRESENTED','ATTORNEY_REPRESENTED','OTHER');
CREATE TYPE "SellerFollowUpStatus" AS ENUM ('SCHEDULED','DUE','COMPLETED','CANCELLED','SUPPRESSED');
CREATE TYPE "SellerOfferStatus" AS ENUM ('DRAFT','OWNER_APPROVED','DELIVERED_MANUALLY','ACCEPTED','REJECTED','WITHDRAWN','EXPIRED');
CREATE TYPE "SellerDispositionReason" AS ENUM ('SELLER_REJECTED_PRICE','SELLER_CHOSE_ANOTHER_BUYER','SELLER_WITHDREW','UNABLE_TO_CONTACT','AUTHORITY_UNVERIFIED','SPREAD_BELOW_TARGET','COMPLIANCE_BLOCK','NURTURE','OPT_OUT','OTHER');

CREATE TABLE "SellerContactAttempt" ("id" TEXT PRIMARY KEY,"engagementId" TEXT NOT NULL,"channel" "EngagementChannel" NOT NULL,"status" "SellerContactAttemptStatus" NOT NULL DEFAULT 'DRAFT',"senderIdentity" TEXT,"provider" TEXT,"draftContentHash" TEXT,"disclosureVersion" TEXT,"consentId" TEXT,"policyId" TEXT,"suppressionCheckedAt" TIMESTAMP(3),"permittedWindowCheckedAt" TIMESTAMP(3),"ownerApprovedAt" TIMESTAMP(3),"ownerApprovedBy" TEXT,"attemptedAt" TIMESTAMP(3),"providerReference" TEXT,"result" TEXT,"sourceUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SellerContactAttempt_engagementId_fkey" FOREIGN KEY ("engagementId") REFERENCES "SellerEngagement"("id") ON DELETE RESTRICT,CONSTRAINT "SellerContactAttempt_delivery_gate" CHECK ("status" NOT IN ('DELIVERED','MANUALLY_RECORDED') OR ("ownerApprovedAt" IS NOT NULL AND "ownerApprovedBy" IS NOT NULL AND "suppressionCheckedAt" IS NOT NULL AND "permittedWindowCheckedAt" IS NOT NULL)));
CREATE INDEX "SellerContactAttempt_engagementId_status_createdAt_idx" ON "SellerContactAttempt"("engagementId","status","createdAt");
CREATE TABLE "SellerConversation" ("id" TEXT PRIMARY KEY,"engagementId" TEXT NOT NULL,"contactAttemptId" TEXT,"occurredAt" TIMESTAMP(3) NOT NULL,"sourceType" TEXT NOT NULL,"sourceUrl" TEXT,"sourceArtifactHash" TEXT,"summary" TEXT NOT NULL,"objections" TEXT[],"questions" TEXT[],"recordedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SellerConversation_engagementId_fkey" FOREIGN KEY ("engagementId") REFERENCES "SellerEngagement"("id") ON DELETE RESTRICT,CONSTRAINT "SellerConversation_contactAttemptId_fkey" FOREIGN KEY ("contactAttemptId") REFERENCES "SellerContactAttempt"("id") ON DELETE RESTRICT);
CREATE INDEX "SellerConversation_engagementId_occurredAt_idx" ON "SellerConversation"("engagementId","occurredAt");
CREATE TABLE "SellerFactVersion" ("id" TEXT PRIMARY KEY,"engagementId" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"version" INTEGER NOT NULL,"priorities" TEXT[],"timeline" TEXT,"propertyCondition" TEXT,"desiredProceedsCents" BIGINT,"minimumNetProceedsCents" BIGINT,"authorityStatus" "SellerAuthorityStatus" NOT NULL,"authoritySourceUrl" TEXT,"representationStatus" "SellerRepresentationStatus" NOT NULL,"preferredChannel" "EngagementChannel","independentAdviceOfferedAt" TIMESTAMP(3),"sellerStatedAt" TIMESTAMP(3) NOT NULL,"recordedBy" TEXT NOT NULL,"correctionReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SellerFactVersion_engagementId_fkey" FOREIGN KEY ("engagementId") REFERENCES "SellerEngagement"("id") ON DELETE RESTRICT,CONSTRAINT "SellerFactVersion_conversationId_fkey" FOREIGN KEY ("conversationId") REFERENCES "SellerConversation"("id") ON DELETE RESTRICT,CONSTRAINT "SellerFactVersion_proceeds_check" CHECK (COALESCE("desiredProceedsCents",0) >= 0 AND COALESCE("minimumNetProceedsCents",0) >= 0),CONSTRAINT "SellerFactVersion_authority_check" CHECK ("authorityStatus" NOT IN ('DOCUMENTED','VERIFIED') OR "authoritySourceUrl" IS NOT NULL));
CREATE UNIQUE INDEX "SellerFactVersion_engagementId_version_key" ON "SellerFactVersion"("engagementId","version");
CREATE INDEX "SellerFactVersion_engagementId_sellerStatedAt_idx" ON "SellerFactVersion"("engagementId","sellerStatedAt");
CREATE TABLE "SellerFollowUp" ("id" TEXT PRIMARY KEY,"engagementId" TEXT NOT NULL,"status" "SellerFollowUpStatus" NOT NULL DEFAULT 'SCHEDULED',"dueAt" TIMESTAMP(3) NOT NULL,"reason" TEXT NOT NULL,"channel" "EngagementChannel","createdBy" TEXT NOT NULL,"completedAt" TIMESTAMP(3),"completionNote" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SellerFollowUp_engagementId_fkey" FOREIGN KEY ("engagementId") REFERENCES "SellerEngagement"("id") ON DELETE RESTRICT);
CREATE INDEX "SellerFollowUp_status_dueAt_idx" ON "SellerFollowUp"("status","dueAt"); CREATE INDEX "SellerFollowUp_engagementId_dueAt_idx" ON "SellerFollowUp"("engagementId","dueAt");
CREATE TABLE "SellerOfferHistory" ("id" TEXT PRIMARY KEY,"engagementId" TEXT NOT NULL,"version" INTEGER NOT NULL,"status" "SellerOfferStatus" NOT NULL DEFAULT 'DRAFT',"offerPriceCents" BIGINT NOT NULL,"sellerNetCents" BIGINT,"financialProjectionId" TEXT,"documentVersionId" TEXT,"assumptions" TEXT[],"expiresAt" TIMESTAMP(3),"ownerApprovedAt" TIMESTAMP(3),"ownerApprovedBy" TEXT,"deliveredAt" TIMESTAMP(3),"responseAt" TIMESTAMP(3),"responseNotes" TEXT,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SellerOfferHistory_engagementId_fkey" FOREIGN KEY ("engagementId") REFERENCES "SellerEngagement"("id") ON DELETE RESTRICT,CONSTRAINT "SellerOfferHistory_price_check" CHECK ("offerPriceCents" >= 0 AND COALESCE("sellerNetCents",0) >= 0),CONSTRAINT "SellerOfferHistory_approval_check" CHECK ("status" = 'DRAFT' OR ("ownerApprovedAt" IS NOT NULL AND "ownerApprovedBy" IS NOT NULL)));
CREATE UNIQUE INDEX "SellerOfferHistory_engagementId_version_key" ON "SellerOfferHistory"("engagementId","version"); CREATE INDEX "SellerOfferHistory_status_expiresAt_idx" ON "SellerOfferHistory"("status","expiresAt");
CREATE TABLE "SellerLeadDisposition" ("id" TEXT PRIMARY KEY,"engagementId" TEXT NOT NULL,"reason" "SellerDispositionReason" NOT NULL,"explanation" TEXT,"nurtureUntil" TIMESTAMP(3),"decidedBy" TEXT NOT NULL,"decidedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SellerLeadDisposition_engagementId_fkey" FOREIGN KEY ("engagementId") REFERENCES "SellerEngagement"("id") ON DELETE RESTRICT,CONSTRAINT "SellerLeadDisposition_other_check" CHECK ("reason" <> 'OTHER' OR "explanation" IS NOT NULL)); CREATE INDEX "SellerLeadDisposition_reason_decidedAt_idx" ON "SellerLeadDisposition"("reason","decidedAt");
CREATE TABLE "CommunicationPolicyProcedure" ("id" TEXT PRIMARY KEY,"jurisdictionState" TEXT NOT NULL,"channel" "EngagementChannel" NOT NULL,"version" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"procedureText" TEXT NOT NULL,"requiredDisclosure" TEXT,"permittedStartLocal" TEXT,"permittedEndLocal" TEXT,"counselSourceUrl" TEXT,"counselApprovedAt" TIMESTAMP(3),"effectiveAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommunicationPolicyProcedure_activation_check" CHECK ("status" <> 'ACTIVE' OR ("counselSourceUrl" IS NOT NULL AND "counselApprovedAt" IS NOT NULL AND "effectiveAt" IS NOT NULL AND "expiresAt" IS NOT NULL)));
CREATE UNIQUE INDEX "CommunicationPolicyProcedure_jurisdictionState_channel_version_key" ON "CommunicationPolicyProcedure"("jurisdictionState","channel","version"); CREATE INDEX "CommunicationPolicyProcedure_status_effectiveAt_expiresAt_idx" ON "CommunicationPolicyProcedure"("status","effectiveAt","expiresAt");
CREATE TABLE "CommunicationTrainingAcknowledgment" ("id" TEXT PRIMARY KEY,"procedureId" TEXT NOT NULL,"actor" TEXT NOT NULL,"acknowledgedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"evidenceHash" TEXT,CONSTRAINT "CommunicationTrainingAcknowledgment_procedureId_fkey" FOREIGN KEY ("procedureId") REFERENCES "CommunicationPolicyProcedure"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "CommunicationTrainingAcknowledgment_procedureId_actor_key" ON "CommunicationTrainingAcknowledgment"("procedureId","actor");
CREATE TABLE "CommunicationListScrub" ("id" TEXT PRIMARY KEY,"procedureId" TEXT NOT NULL,"source" TEXT NOT NULL,"sourceUrl" TEXT,"artifactHash" TEXT,"recordCount" INTEGER NOT NULL,"scrubbedAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"reviewedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommunicationListScrub_procedureId_fkey" FOREIGN KEY ("procedureId") REFERENCES "CommunicationPolicyProcedure"("id") ON DELETE RESTRICT); CREATE INDEX "CommunicationListScrub_scrubbedAt_expiresAt_idx" ON "CommunicationListScrub"("scrubbedAt","expiresAt");
CREATE TABLE "CommunicationProviderLog" ("id" TEXT PRIMARY KEY,"contactAttemptId" TEXT NOT NULL,"provider" TEXT NOT NULL,"environment" TEXT NOT NULL,"eventType" TEXT NOT NULL,"externalReference" TEXT,"idempotencyKey" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"webhookVerified" BOOLEAN NOT NULL DEFAULT false,"occurredAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommunicationProviderLog_contactAttemptId_fkey" FOREIGN KEY ("contactAttemptId") REFERENCES "SellerContactAttempt"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "CommunicationProviderLog_idempotencyKey_key" ON "CommunicationProviderLog"("idempotencyKey"); CREATE INDEX "CommunicationProviderLog_contactAttemptId_occurredAt_idx" ON "CommunicationProviderLog"("contactAttemptId","occurredAt");
